def charger(nom):
    chemin = os.path.join(BASE, nom)
    with io.open(chemin, encoding='utf-8') as f:
        return json.load(f), chemin

def sauver(nom, data, chemin):
    with io.open(chemin, 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
        f.write('\n')

for nom_fichier, ajout, mode_label in [('corpus-adulte.json', ADULTES, 'adulte'), ('corpus-enfant.json', ENFANTS, 'enfant')]:
    data, chemin = charger(nom_fichier)
    codes_existants = {e['code'] for e in data}
    nouveaux = [e for e in ajout if e['code'] not in codes_existants]
    data.extend(nouveaux)
    sauver(nom_fichier, data, chemin)
    print(f"{mode_label}: +{len(nouveaux)} entrées → {len(data)} au total dans {nom_fichier}")

# contrôle final
a, _ = charger('corpus-adulte.json')
e, _ = charger('corpus-enfant.json')
print(f"CORPUS FINAL : {len(a) + len(e)} paraboles (adulte {len(a)} / enfant {len(e)})")
assert len(a) + len(e) == 100, "le corpus doit atteindre 100"
print("OK — objectif 100 atteint.")
